+JNIEXPORT jint JNICALL
+Java_jvmti_JVMTIUtils_getThreadState(JNIEnv *jni, jclass cls, jthread thread) {
+  jint state = 0;
+  jvmtiError err = jvmti->GetThreadState(thread, &state);
+  check_jvmti_status(jni, err, "Error during GetThreadState()");
+  return state;
+}
